public static int nullSafeHashCode(long[] array) {
    if (array == null) {
        return 0;
    }
    int result = 1;
    for (long value : array) {
        result = 31 * result + (int) (value ^ (value >>> 32));
    }
    return result;
}

public static int nullSafeHashCode(long[] array) {
    if (array == null) {
        return 0;
    }
    int hash = 1;
    for (int i = 0; i < array.length; i++) {
        long element = array[i];
        int part1 = (int) (element ^ (element >>> 32));
        int part2 = (int) (element >>> 16);
        hash = 31 * hash + part1;
        hash = 31 * hash + part2;
    }
    return hash;
}

