IsomorphicGraphMapping<V,E> function ( Graph<V,E> graph ) { 
    int size = graph.vertexSet( ).size( ) ; 
    int[] mapping = new int[size] ; 
    Integer[] indices = new Integer[size] ; 
    for ( int i = 0 ; i < size ; ++ i ) { 
        indices[i] = i ; 
    } 
    Arrays.sort( indices , new Comparator<Integer>( ) { 
        public int compare(Integer a , Integer b) { 
            return graph.outDegreeOf(a).compareTo(graph.outDegreeOf(b)); 
        } 
    } ) ; 
    for ( int i = 0 ; i < size ; ++ i ) { 
        mapping[indices[i]] = i ; 
    } 
    return new IsomorphicGraphMapping<V,E>(graph,mapping); 
}

