public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getByteSize(message);
    out.write(ProtoUtils.encodeVarint32(size));
    schema.writeTo(buffer, message);
    out.write(buffer.getUnsafeArray(), 0, buffer.size());
    return size + buffer.size();
}

int function(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    ByteBuffer byteBuffer = schema.toByteArray(message);
    byte[] bytes = byteBuffer.array();
    int size = bytes.length;
    out.write(size >>> 24);
    out.write((size >>> 16) & 0xFF);
    out.write((size >>> 8) & 0xFF);
    out.write(size & 0xFF);
    out.write(bytes);
