public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if ((c & 0x80) == 0) { // 1-byte
            size++;
        } else if ((c & 0xE0) == 0xE0) { // 2-byte
            size += 2;
        } else if ((c & 0xF0) == 0xF0) { // 3-byte
            size += 3;
        } else if ((c & 0xF8) == 0xF8) { // 4-byte
            size += 4;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int count = 0;
    for (int i = index, end = index + len; i < end; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            count += 1;
        } else if (c <= 0x7FF) {
            count += 2;
        } else if (c <= 0xFFFF) {
            count += 3;
        } else {
            count += 4;
        }
    }
    return count;
}

