public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int charCount = str.length();
    int utf8Length = 0;
    for (int i = 0; i < charCount; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            utf8Length += 1;
        } else if (c <= 0x7FF) {
            utf8Length += 2;
        } else if (c < 0xD800 || c > 0xDBFF) {
            utf8Length += 3;
        } else {
            i++;
            utf8Length += 4;
        }
    }

    if (lb.offset + utf8Length > lb.buffer.length) {
        lb = LinkedBuffer.expand(lb, utf8Length);
    }

    for (int i = 0; i < charCount; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            lb.buffer[lb.offset++] = (byte) c;
        } else if (c <= 0x7FF) {
            lb.buffer[lb.offset++] = (byte) (0xC0 | (c >>> 6));
            lb.buffer[lb.offset++] = (byte) (0x80 | (c & 0x3F));
        } else if (c < 0xD800 || c > 0xDBFF) {
            lb.buffer[lb.offset++] = (byte) (0xE0 | (c >>> 12));
            lb.buffer[lb.offset++] = (byte) (0x80 | ((c >>> 6) & 0x3F));
            lb.buffer[lb.offset++] = (byte) (0x80 | (c & 0x3F));
        } else {
            i++;
            int codePoint = ((c & 0x3FF) << 10) | (str.charAt(i) & 0x3FF);
            lb.buffer[lb.offset++] = (byte) (0xF0 | (codePoint >>> 18));
            lb.buffer[lb.offset++] = (byte) (0x80 | ((codePoint >>> 12) & 0x3F));
            lb.buffer[lb.offset++] = (byte) (0x80 | ((codePoint >>> 6) & 0x3F));
            lb.buffer[lb.offset++] = (byte) (0x80 | (codePoint & 0x3F));
        }
    }

    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    try {
        byte[] bytes = str.toString().getBytes(StandardCharsets.UTF_8);
        int length = bytes.length;
        if (lb.run() + length > lb.limit()) {
            lb = LinkedBuffer.expand(lb, length);
        }
        System.arraycopy(bytes, 0, lb.buf, lb.run(), length);
        lb.run() += length;
    } catch (IOException e) {
        throw new RuntimeException(e);
    }
    return lb;
}

