    long tmp = (long) desiredCapacity + (desiredCapacity >> 3);
    tmp += ((tmp >> 6) + 1) * 3;
    int res = (int) (tmp * 11) >>> 10;
    return (res < desiredCapacity) ? nextPrime(res) : res;
