private static boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    if (number <= 3) {
        return true;
    }
    if (number % 2 == 0 || number % 3 == 0) {
        return false;
    }
    for (int i = 5; i * i <= number; i += 6) {
        if (number % i == 0 || number % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

public static int nextPrime(int desiredCapacity){
    int capacity = desiredCapacity;
    if (capacity < 2) {
        capacity = 2;
    }
    while (!isPrime(capacity)) {
        capacity++;
        if (desiredCapacity >= 1000 && Math.abs(capacity - desiredCapacity) > capacity * 0.11) {
            capacity = (int) (desiredCapacity * 1.11);
        }
    }
    return capacity;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 11) {
        return 11;
    }

    while (!isPrime(desiredCapacity)) {
        desiredCapacity++;
    }

    int adjustment = desiredCapacity * 11 / 100;
    if (desiredCapacity >= 1000) {
        adjustment = 11;
    }

    return Math.min(desiredCapacity + adjustment, Integer.MAX_VALUE / 2);
}

public static int nextPrime(int desiredCapacity) {
    int capacity = desiredCapacity;
    if (capacity < 11) {
        capacity = 11;
    } else {
        capacity += (capacity * 11) / 100;
