public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    boolean nextIsEscaped = false;
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (nextIsEscaped) {
            switch (c) {
                case 'n':
                    sb.append('\n');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
