                    sb.append('\f');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '"':
                    sb.append('"');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    sb.append('\\').append(c);
                    break;
            }
            nextIsEscaped = false;
        } else {
            if (c == '\\') {
                nextIsEscaped = true;
            } else {
                sb.append(c);
            }
        }
    }
    return sb.toString();
}

